#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstdio>
using namespace std;

using i64 = long long;

const int INF = 0x7f7f7f7f;
const int MAX_NODES = 5010000;
const int MOD = 1000000007;

struct Arc {
    int destination;
    int remaining;
    int weight;
    int next;
};

vector<Arc> network;
vector<int> first;

void link(int u, int v, int cap, int cost) {
    network.push_back({v, cap, cost, first[u]});
    first[u] = static_cast<int>(network.size()) - 1;
    network.push_back({u, 0, -cost, first[v]});
    first[v] = static_cast<int>(network.size()) - 1;
}

void readInt(int &val) {
    val = 0;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') break;
        ch = getchar();
    }
    bool negative = false;
    if (ch == '-') {
        negative = true;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        val = val * 10 + (ch - '0');
        ch = getchar();
    }
    if (negative) val = -val;
}

void printInt(int val) {
    if (val < 0) {
        putchar('-');
        val = -val;
    }
    if (val > 9) printInt(val / 10);
    putchar(val % 10 + '0');
}

void println(int val) {
    printInt(val);
    putchar('\n');
}

int source, sink;
vector<int> dist, flow, prevNode, prevArc;
vector<bool> inQ;

bool spfa() {
    fill(dist.begin(), dist.end(), INF);
    fill(flow.begin(), flow.end(), 0);
    fill(prevNode.begin(), prevNode.end(), -1);
    fill(prevArc.begin(), prevArc.end(), -1);
    fill(inQ.begin(), inQ.end(), false);

    queue<int> q;
    dist[source] = 0;
    flow[source] = INF;
    q.push(source);
    inQ[source] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inQ[u] = false;

        for (int idx = first[u]; idx != -1; idx = network[idx].next) {
            int v = network[idx].destination;
            int cap = network[idx].remaining;
            int cost = network[idx].weight;

            if (cap > 0 && dist[v] > dist[u] + cost) {
                dist[v] = dist[u] + cost;
                flow[v] = min(flow[u], cap);
                prevNode[v] = u;
                prevArc[v] = idx;
                if (!inQ[v]) {
                    q.push(v);
                    inQ[v] = true;
                }
            }
        }
    }

    return prevNode[sink] != -1;
}

int totalFlow, minCost;

void minCostFlow() {
    while (spfa()) {
        int augment = flow[sink];
        totalFlow += augment;
        minCost += augment * dist[sink];

        int cur = sink;
        while (cur != source) {
            network[prevArc[cur]].remaining -= augment;
            network[prevArc[cur] ^ 1].remaining += augment;
            cur = prevNode[cur];
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    readInt(n); readInt(m); readInt(k); readInt(c); readInt(d);

    int B = max(n, k);
    source = n * (2 * B + 1) + 1;
    sink = source + 1;

    dist.resize(sink + 1);
    flow.resize(sink + 1);
    prevNode.resize(sink + 1);
    prevArc.resize(sink + 1);
    inQ.resize(sink + 1);
    first.assign(sink + 1, -1);

    for (int i = 0; i < k; i++) {
        int x;
        readInt(x);
        link(source, x, 1, 0);
    }

    link(n * (2 * B) + 1, sink, INF, 0);

    for (int layer = 0; layer < 2 * B; layer++) {
        link(layer * n + 1, (layer + 1) * n + 1, INF, 0);
        for (int i = 2; i <= n; i++) {
            link(layer * n + i, (layer + 1) * n + i, INF, c);
        }
    }

    for (int i = 0; i < m; i++) {
        int x, y;
        readInt(x); readInt(y);
        for (int layer = 0; layer < 2 * B; layer++) {
            for (int j = 1; j <= k; j++) {
                int cost = d * (2 * j - 1) + c;
                link(layer * n + x, (layer + 1) * n + y, 1, cost);
                link(layer * n + y, (layer + 1) * n + x, 1, cost);
            }
        }
    }

    minCostFlow();
    println(minCost);

    return 0;
}
